#[inductive(readonly_apply)]
fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    let read_state = pre.local_reads[rid];
    match read_state {
        ReadonlyState::ReadyToRead { op, node_id, version_upper_bound } => {
            // Get the state that was used for the read operation
            let state = pre.replicas[node_id];

            // From the replica_state invariant, we know:
            // state == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id))

            // The result of the read operation
            let ret = DT::dispatch_spec(state, op);

            // We need to show that there exists a version v such that:
            // 1. version_upper_bound <= v <= post.version_upper_bound
            // 2. ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)

            // We can use the current local version as our v
            let v = pre.current_local_version(node_id);

            // Show that version_upper_bound <= v
            // From the wf_readstate invariant for ReadyToRead:
            // version_upper_bound <= pre.version_upper_bound
            // version_upper_bound <= pre.current_local_version(node_id)
            assert(version_upper_bound <= v);

            // Show that v <= post.version_upper_bound
            // Since the readonly_apply transition doesn't change version_upper_bound:
            assert(post.version_upper_bound == pre.version_upper_bound);
            // From the wf_readstate invariant:
            assert(v <= pre.version_upper_bound);
            assert(v <= post.version_upper_bound);

            // Show that ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)
            // Since the readonly_apply transition doesn't change the log:
            assert(post.log == pre.log);
            // From the replica_state invariant:
            assert(state == compute_nrstate_at_version(pre.log, v));
            // Therefore:
            assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));
        }
        _ => {}
    }
}

