#[inductive(readonly_apply)]
fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    // Pre-condition: pre.invariant() holds
    // Post-condition: Need to show post.invariant() holds

    // The readonly_apply transition does the following:
    // 1. Removes rid from local_reads with state ReadonlyState::ReadyToRead{op, node_id, version_upper_bound}
    // 2. Requires combiner[node_id] == CombinerState::Ready
    // 3. Requires replicas[node_id] == state
    // 4. Adds rid to local_reads with state ReadonlyState::Done{op, node_id, version_upper_bound, ret}
    //    where ret = DT::dispatch_spec(state, op)

    // We need to show that all invariants hold in the post state.
    // Most invariants are preserved because the transition only affects local_reads[rid].

    // Focus on the invariant that's failing: inv_read_results
    // This requires showing that for all rid' in post.local_reads,
    // read_results_match(post.local_reads[rid']) holds.

    assert forall |rid_p| #[trigger] post.local_reads.contains_key(rid_p) implies post.read_results_match(post.local_reads[rid_p]) by {
        if rid_p == rid {
            // This is the entry we modified
            match pre.local_reads[rid] {
                ReadonlyState::ReadyToRead { op, node_id, version_upper_bound } => {
                    // Post state has:
                    // local_reads[rid] = ReadonlyState::Done{op, node_id, version_upper_bound, ret}
                    // where ret = DT::dispatch_spec(pre.replicas[node_id], op)

                    // From pre.invariant() and pre.inv_readonly_requests_wf():
                    assert(pre.wf_readstate(pre.local_reads[rid]));
                    // This gives us:
                    assert(version_upper_bound <= pre.version_upper_bound);
                    assert(version_upper_bound <= pre.current_local_version(node_id));
                    assert(pre.wf_node_id(node_id));

                    // From pre.invariant() and pre.replica_state():
                    assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id)));

                    let v = pre.current_local_version(node_id);
                    assert(rangeincl(version_upper_bound, v, pre.version_upper_bound));
                    assert(DT::dispatch_spec(pre.replicas[node_id], op) == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op));

                    // Since the transition doesn't change log or version_upper_bound:
                    assert(post.log == pre.log);
                    assert(post.version_upper_bound == pre.version_upper_bound);
                    assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
                    assert(DT::dispatch_spec(pre.replicas[node_id], op) == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));

                    // Therefore post.read_results_match(post.local_reads[rid]) holds
                }
                _ => {}
            }
        } else {
            // This entry is unchanged from pre to post
            assert(post.local_reads[rid_p] == pre.local_reads[rid_p]);
            // Since pre.invariant() holds and this entry is unchanged:
            assert(pre.read_results_match(pre.local_reads[rid_p]));
            // Therefore post.read_results_match(post.local_reads[rid_p]) holds
        }
    }
}

