#[inductive(readonly_apply)]
fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    // From preconditions, we know pre.invariant() holds

    // The readonly_apply transition changes exactly one entry in local_reads:
    // from ReadonlyState::ReadyToRead { op, node_id, version_upper_bound }
    // to ReadonlyState::Done { op, node_id, version_upper_bound, ret }
    // where ret = DT::dispatch_spec(pre.replicas[node_id], op)

    // All other invariants are preserved because the transition only modifies local_reads[rid]

    // For the inv_read_results invariant, we need to show:
    // forall |rid_p| post.local_reads.contains_key(rid_p) ==> post.read_results_match(post.local_reads[rid_p])

    assert forall |rid_p| #[trigger] post.local_reads.contains_key(rid_p) implies post.read_results_match(post.local_reads[rid_p]) by {
        if rid_p == rid {
            // This is the entry we modified
            let pre_read_state = pre.local_reads[rid];
            let post_read_state = post.local_reads[rid];
            match (pre_read_state, post_read_state) {
                (ReadonlyState::ReadyToRead { op, node_id, version_upper_bound }, 
                 ReadonlyState::Done { op: op2, node_id: node_id2, version_upper_bound: version_upper_bound2, ret }) => {
                    // Sanity check - these should be the same values
                    assert(op == op2);
                    assert(node_id == node_id2);
                    assert(version_upper_bound == version_upper_bound2);

                    // From pre.invariant() and inv_readonly_requests_wf:
                    assert(pre.wf_readstate(pre_read_state));
                    // This gives us the preconditions we need:
                    assert(pre.wf_node_id(node_id));
                    assert(version_upper_bound <= pre.version_upper_bound);
                    assert(version_upper_bound <= pre.current_local_version(node_id));

                    // From pre.invariant() and replica_state:
                    assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, pre.current_local_version(node_id)));

                    // The result of the operation:
                    let computed_result = DT::dispatch_spec(pre.replicas[node_id], op);
                    assert(ret == computed_result);

                    // Choose v = pre.current_local_version(node_id)
                    let v = pre.current_local_version(node_id);

                    // Show that version_upper_bound <= v <= post.version_upper_bound
                    assert(version_upper_bound <= v);  // From wf_readstate

                    // The transition doesn't change version_upper_bound:
                    assert(post.version_upper_bound == pre.version_upper_bound);
                    assert(v <= pre.version_upper_bound);  // From wf_readstate
                    assert(v <= post.version_upper_bound);

                    // Show that rangeincl(version_upper_bound, v, post.version_upper_bound) holds
                    assert(rangeincl(version_upper_bound, v, post.version_upper_bound));

                    // Show that ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)
                    // The transition doesn't change the log:
                    assert(post.log == pre.log);
                    assert(compute_nrstate_at_version(post.log, v) == compute_nrstate_at_version(pre.log, v));
                    assert(pre.replicas[node_id] == compute_nrstate_at_version(pre.log, v));
                    assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));

                    // Therefore, post.read_results_match(post.local_reads[rid]) holds
                }
                _ => ()
            }
        } else {
            // This entry is unchanged, so the invariant is preserved
            assert(post.local_reads[rid_p] == pre.local_reads[rid_p]);
            // Since pre.invariant() holds, pre.read_results_match(pre.local_reads[rid_p]) holds
            assert(pre.read_results_match(pre.local_reads[rid_p]));
            // Therefore post.read_results_match(post.local_reads[rid_p]) holds
        }
    }
}

