pub proof fn combiner_request_ids_proof(combiners: Map<NodeId, CombinerState>) -> Set<ReqId>
    requires
        combiners.dom().finite(),
    decreases combiners.dom().len(),
{
    if combiners.dom().len() == 0 {
        Set::empty()
    } else {
        let node_id = combiners.dom().choose();
        let s1 = combiner_request_ids_proof(combiners.remove(node_id));
        s1 + seq_to_set(combiners[node_id].queued_ops())
    }
}

proof fn combiner_request_ids_finite(combiners: Map<NodeId, CombinerState>) -> (s: Set<ReqId>)
    requires
        combiners.dom().finite(),
    ensures
        s == combiner_request_ids(combiners),
        s.finite(),
    decreases combiners.dom().len(),
{
    if combiners.dom().len() == 0 {
        Set::empty()
    } else {
        let node_id = combiners.dom().choose();
        let s1 = combiner_request_ids_finite(combiners.remove(node_id));
        s1 + seq_to_set(combiners[node_id].queued_ops())
    }
}

pub open spec fn combiner_request_id_fresh(combiner: Map<NodeId, CombinerState>, rid: ReqId) -> bool {
    forall |n| #[trigger] combiner.contains_key(n) ==> !combiner[n].queued_ops().contains(rid)
}

proof fn combiner_request_ids_not_contains(combiner: Map<NodeId, CombinerState>, rid: ReqId)
    requires
        combiner.dom().finite(),
    ensures
        !combiner_request_ids(combiner).contains(rid) == combiner_request_id_fresh(combiner, rid),
{
    assert(combiner_request_ids(combiner).contains(rid) == !combiner_request_id_fresh(combiner, rid)) by {
        combiner_request_ids_not_contains_proof(combiner, rid);
    }
}

proof fn combiner_request_ids_not_contains_proof(combiner: Map<NodeId, CombinerState>, rid: ReqId)
    requires
        combiner.dom().finite(),
    ensures
        combiner_request_ids(combiner).contains(rid) == !combiner_request_id_fresh(combiner, rid),
    decreases combiner.dom().len(),
{
    if combiner.dom().len() == 0 {
        assert(combiner_request_ids(combiner).contains(rid) == false);
        assert(combiner_request_id_fresh(combiner, rid) == true);
    } else {
        let node_id = combiner.dom().choose();
        let combiner2 = combiner.remove(node_id);
        combiner_request_ids_not_contains_proof(combiner2, rid);
        let req_ids = combiner_request_ids(combiner2);
        let queued_ops = combiner[node_id].queued_ops();
        assert(req_ids.contains(rid) || queued_ops.contains(rid)
            == !combiner_request_id_fresh(combiner, rid));
    }
}

pub closed spec fn get_fresh_nat(reqs: Set<ReqId>, combiner: Map<NodeId, CombinerState>) -> nat
    recommends
        reqs.finite() && combiner.dom().finite(),
{
    choose|n| !reqs.contains(n) && combiner_request_id_fresh(combiner, n)
}

proof fn max_of_set(s: Set<nat>) -> (r: nat)
    requires
        s.finite(),
    ensures
        forall|x: nat| #[trigger] s.contains(x) ==> x <= r,
    decreases s.len(),
{
    if s.is_empty() {
        0
    } else {
        let v1 = s.choose();
        let v2 = max_of_set(s.remove(v1));
        assert(forall|x: nat| #[trigger] s.contains(x) && x != v1 ==> s.remove(v1).contains(x));
        if v1 >= v2 {
            v1
        } else {
            v2
        }
    }
}

proof fn element_outside_set(s: Set<nat>) -> (r: nat)
    requires
        s.finite(),
    ensures
        !s.contains(r),
{
    max_of_set(s) + 1
}

pub proof fn get_fresh_nat_not_in(reqs: Set<ReqId>, combiner: Map<NodeId, CombinerState>)
    requires
        reqs.finite(),
        combiner.dom().finite(),
    ensures
        !reqs.contains(get_fresh_nat(reqs, combiner)),
        combiner_request_id_fresh(combiner, get_fresh_nat(reqs, combiner)),
{
    let rid = get_fresh_nat(reqs, combiner);
    let combiner_req_ids = combiner_request_ids(combiner);
    assert(!combiner_req_ids.contains(rid) == combiner_request_id_fresh(combiner, rid)) by {
        combiner_request_ids_not_contains(combiner, rid);
    }
    assert(combiner_req_ids.finite()) by {
        combiner_request_ids_finite(combiner);
    }
    let req_ids = reqs + combiner_req_ids;
    assert(req_ids.finite());
    let r = element_outside_set(req_ids);
    // let r = choose |r| !req_ids.contains(r);
    assert(!reqs.contains(r));
    assert(!combiner_req_ids.contains(r));
    assert(combiner_request_id_fresh(combiner, r)) by {
        combiner_request_ids_not_contains(combiner, r);
    }
    assert(exists|n| !reqs.contains(n) && combiner_request_id_fresh(combiner, n));
}

/// the log contains all entries up to, but not including the provided end
pub open spec fn LogContainsEntriesUpToHere<DT: Dispatch>(
    log: Map<LogIdx, LogEntry<DT>>,
    end: LogIdx,
) -> bool {
    forall|i: nat| 0 <= i < end ==> log.contains_key(i)
}

/// the log doesn't contain any entries at or above the provided start index
pub open spec fn LogNoEntriesFromHere<DT: Dispatch>(
    log: Map<LogIdx, LogEntry<DT>>,
    start: LogIdx,
) -> bool {
    forall|i: nat| i >= start ==> !log.contains_key(i)
}

pub open spec fn LogRangeNoNodeId<DT: Dispatch>(
    log: Map<nat, LogEntry<DT>>,
    lower: nat,
    upper: nat,
    node_id: NodeId,
) -> bool {
    forall|i: nat| #![auto] lower <= i < upper ==> log.contains_key(i) && log[i].node_id != node_id
}

/// This predicate describes the relationship between the queued_ops in the combiner and
/// the log entries. Specifically, it says that for entries in the log between
/// logIndexLower and logIndexUpper, if the entry's node_id matches the given nodeId,
/// then there should be a corresponding entry in queued_ops at position queueIndex + k,
/// where k is the count of matching log entries we've seen so far.
pub open spec fn LogRangeMatchesQueue<DT: Dispatch>(
    queuedOps: Seq<ReqId>,
    log: Map<nat, LogEntry<DT>>,
    queueIndex: nat,
    logIndexLower: LogIdx,
    logIndexUpper: LogIdx,
    nodeId: NodeId,
    localUpdates: Map<ReqId, UpdateState<DT>>,
) -> bool
    recommends
        queueIndex <= queuedOps.len(),
        logIndexLower <= logIndexUpper,
{
    // This is a complex invariant that relates the queued operations in the combiner
    // to the actual log entries.
    //
    // For each log entry between logIndexLower and logIndexUpper:
    //  - If the entry's node_id matches nodeId, then:
    //     * There should be a corresponding entry in queuedOps at position queueIndex + k
    //       where k is the count of matching entries we've seen so far
    //     * That queued operation should be in the localUpdates map in the Placed state
    //     * The index in the Placed state should match the log index
    //
    // This essentially says that the queued operations correspond to the log entries
    // for this node, in the same order.

    forall |log_idx: nat|
        logIndexLower <= log_idx < logIndexUpper && #[trigger] log.contains_key(log_idx)
        && log[log_idx].node_id == nodeId ==> exists |k: nat|
            0 <= k < logIndexUpper - logIndexLower
            && queueIndex + k < queuedOps.len()
            && log_idx == logIndexLower + smallest_skipped(nat_to_set(logIndexLower, log_idx), |j: nat|
                log.contains_key(j) && log[j].node_id == nodeId)
            && localUpdates.contains_key(queuedOps[queueIndex + k])
            && localUpdates[queuedOps[queueIndex + k]].is_Placed()
            && localUpdates[queuedOps[queueIndex + k]].get_Placed_idx() == log_idx
}

proof fn LogRangeMatchesQueue_update_change<DT: Dispatch>(
    queuedOps: Seq<ReqId>,
    log: Map<nat, LogEntry<DT>>,
    queueIndex: nat,
    logIndexLower: LogIdx,
    logIndexUpper: LogIdx,
    nodeId: NodeId,
    localUpdatesPre: Map<ReqId, UpdateState<DT>>,
    localUpdatesPost: Map<ReqId, UpdateState<DT>>,
)
    requires
        LogRangeMatchesQueue(queuedOps, log, queueIndex, logIndexLower, logIndexUpper, nodeId, localUpdatesPre),
        forall |rid|
            localUpdatesPre.contains_key(rid) && !localUpdatesPost.contains_key(rid) ==> rid
                == queuedOps.last(),
        forall |rid|
            localUpdatesPre.contains_key(rid) && localUpdatesPost.contains_key(rid) ==> localUpdatesPre[rid]
                == localUpdatesPost[rid],
        forall |rid|
            !localUpdatesPre.contains_key(rid) && localUpdatesPost.contains_key(rid) ==> exists |idx|
                log.contains_key(idx) && log[idx].op == localUpdatesPost[rid].get_Init_op()
                && localUpdatesPost[rid].is_Init() && idx == logIndexLower - 1,
    ensures
        LogRangeMatchesQueue(queuedOps.drop_last(), log, queueIndex, logIndexLower, logIndexUpper, nodeId, localUpdatesPost),
{
}

proof fn LogRangeMatchesQueue_update_change_2<DT: Dispatch>(
    queuedOps: Seq<ReqId>,
    log: Map<nat, LogEntry<DT>>,
    queueIndex: nat,
    logIndexLower: LogIdx,
    logIndexUpper: LogIdx,
