}

proof fn LogRangeMatchesQueue_append<DT: Dispatch>(
    queuedOps: Seq<ReqId>,
    log: Map<nat, LogEntry<DT>>,
    queueIndex: nat,
    logIndexLower: LogIdx,
    logIndexUpper: LogIdx,
    nodeId: NodeId,
    localUpdates: Map<ReqId, UpdateState<DT>>,
    rid: ReqId,
    idx: LogIdx,
)
    requires
