pub open spec fn compute_nrstate_at_version<DT: Dispatch>(
    log: Map<LogIdx, LogEntry<DT>>,
    version: LogIdx,
) -> DT::View
    recommends
        forall|i| 0 <= i < version ==> log.contains_key(i),
    decreases version,
{
    if version == 0 {
        DT::init_spec()
    } else {
        let ver = (version - 1) as nat;
        DT::dispatch_mut_spec(compute_nrstate_at_version(log, ver), log[ver].op).0
    }
}

pub proof fn compute_nrstate_at_version_preserves<DT: Dispatch>(
    a: Map<LogIdx, LogEntry<DT>>,
    b: Map<LogIdx, LogEntry<DT>>,
    version: LogIdx,
)
    requires
        forall|i| 0 <= i < version ==> a.contains_key(i),
        forall|i| 0 <= i < version ==> a[i] == b[i],
    ensures
        compute_nrstate_at_version(a, version) == compute_nrstate_at_version(b, version),
    decreases version,
{
    if version == 0 {
    } else {
        let ver = (version - 1) as nat;
        compute_nrstate_at_version_preserves(a, b, ver);
    }
}

pub proof fn compute_nrstate_at_version_append<DT: Dispatch>(
    log: Map<LogIdx, LogEntry<DT>>,
    version: LogIdx,
    entry: LogEntry<DT>,
)
    requires
        forall|i| 0 <= i < version ==> log.contains_key(i),
    ensures
        compute_nrstate_at_version(log.insert(version, entry), version + 1) == DT::dispatch_mut_spec(
            compute_nrstate_at_version(log, version),
            entry.op,
        ).0,
    decreases version,
{
    if version == 0 {
        assert(log.insert(0, entry)[0] == entry);
    } else {
        let ver = (version - 1) as nat;
        assert(log.insert(version, entry)[ver] == log[ver]);
        compute_nrstate_at_version_append(log, ver, entry);
    }
}

pub open spec fn smallest_skipped(s: Set<nat>, pred: spec_fn(nat) -> bool) -> nat
    recommends s.finite()
    decreases s.len()
{
    if s.is_empty() {
        0
    } else {
        let n = s.choose();
        let v = smallest_skipped(s.remove(n), pred);
        if pred(n) && n < v {
            n
        } else {
            v
        }
    }
}

pub open spec fn nat_to_set(lo: nat, hi: nat) -> Set<nat>
    recommends lo <= hi
{
    Set::new(|n: nat| lo <= n < hi)
}

